package com.example.semantic.model

/**
 * Confidence Levels specified by MSIL
 * >= 0.85: EXECUTE
 * 0.60 - 0.84: ASK_FOR_CLARIFICATION
 * < 0.60: ASK_USER_TO_REPEAT
 */
enum class ConfidenceLevel {
    EXECUTE,
    ASK_FOR_CLARIFICATION,
    ASK_USER_TO_REPEAT
}

/**
 * Action Plan generated by Myanmar Semantic Intelligence Layer.
 * Decoupled from direct execution; evaluated by ActionSafetyValidator and executed by existing Android dispatchers.
 */
data class ActionPlan(
    val intent: SemanticIntent,
    val target: String? = null,
    val actionType: String = intent.name,
    val parameters: Map<String, Any?> = emptyMap(),
    val confidence: Float = 1.0f,
    val confidenceLevel: ConfidenceLevel = if (confidence >= 0.85f) ConfidenceLevel.EXECUTE else if (confidence >= 0.60f) ConfidenceLevel.ASK_FOR_CLARIFICATION else ConfidenceLevel.ASK_USER_TO_REPEAT,
    val requiresConfirmation: Boolean = false,
    val confirmationPrompt: String? = null,
    val clarificationPrompt: String? = null,
    val speechFeedbackMM: String? = null,
    val fallbackAction: String? = null,
    val explanation: String? = null,
    val isExecutable: Boolean = true,
    val safetyStatus: String = "SAFE"
)
